// Material PixelOrdered (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_atlas: texture_2d<f32>;
@group(2) @binding(2) var material_sampler: sampler;

fn pixel_srgb_to_linear(c: vec3f) -> vec3f {
 return select(pow((c+vec3f(0.055))/1.055,vec3f(2.4)),c/12.92,c<=vec3f(0.04045));
}

// The atlas is this material's own declared texture binding. Integer loads
// select original mip-zero texels even when the logical canvas shrinks.
fn pixel_load(p: vec2f) -> vec4f { return textureLoad(tex_atlas,vec2i(floor(p)),0); }

const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = in.instance_params.xy;
  let v1: vec2f = in.instance_params.zw;
  let v2: vec2f = (in.uv * v1);
  let v3: vec2f = (v0 + v2);
  let v4: f32 = in.instance_params.x;
  let v5: f32 = abs(v4);
  let v6: f32 = in.instance_params.z;
  let v7: f32 = abs(v6);
  let v8: f32 = (v5 + v7);
  let v9: f32 = step(0.000001, v8);
  let v10: vec2f = vec2f(v9);
  let v11: vec2f = mix(in.uv, v3, v10);
  let v12: vec2f = vec2f(2048.0, 1024.0);
  let v13: vec2f = (v11 * v12);
  let v14: vec4f = pixel_load(v13);
  let v15: vec3f = v14.xyz;
  let v16: vec3f = in.color.xyz;
  let v17: f32 = v11.x;
  let v18: f32 = step(v17, -0.5);
  let v19: vec3f = vec3f(v18);
  let v20: vec3f = mix(v15, v16, v19);
  let v21: vec3f = vec3f(0.03137254901960784, 0.047058823529411764, 0.10588235294117647);
  let v22: vec3f = (v20 * 0.09803921568627451);
  let v23: vec3f = (v21 + v22);
  let v24: vec4f = material_global(0u);
  let v25: f32 = v24.z;
  let v26: f32 = in.world_pos.x;
  let v27: f32 = step(108.0, v26);
  let v28: f32 = (v25 * v27);
  let v29: f32 = step(v26, 660.0);
  let v30: f32 = (v28 * v29);
  let v31: f32 = v24.y;
  let v32: f32 = in.world_pos.y;
  let v33: f32 = -(v32);
  let v34: f32 = (v33 + 720.0);
  let v35: f32 = step(v31, v34);
  let v36: f32 = (v30 * v35);
  let v37: f32 = (v31 + 82.0);
  let v38: f32 = step(v34, v37);
  let v39: f32 = (v36 * v38);
  let v40: vec3f = vec3f(v39);
  let v41: vec3f = mix(v20, v23, v40);
  let v42: f32 = v24.x;
  let v43: f32 = -(v42);
  let v44: f32 = (v43 + 1.0);
  let v45: vec3f = (v41 * v44);
  let v46: vec3f = pixel_srgb_to_linear(v45);
  let v47: f32 = v14.w;
  let v48: f32 = mix(v47, 1.0, v18);
  out.base_color = v46;
  out.alpha = v48;
  return out;
}
